// Generates src/fonts/*.c from the Barlow TTFs in tools/ttf using lv_font_conv.
// Run from the firmware folder:  node tools/make_fonts.mjs
// Only needed if you change sizes or characters; the generated files are committed.
import { execFileSync } from "node:child_process";
import { writeFileSync, mkdirSync } from "node:fs";

const TTF = {
  c7: "tools/ttf/BarlowCondensed-Bold.ttf",
  c6: "tools/ttf/BarlowCondensed-SemiBold.ttf",
  b7: "tools/ttf/Barlow-Bold.ttf",
  b6: "tools/ttf/Barlow-SemiBold.ttf",
  b5: "tools/ttf/Barlow-Medium.ttf",
};
// ASCII + Latin-1 (Hülkenberg, Pérez, São Paulo) + – ’ …  (Barlow has no arrow glyph; arrows are drawn as lines)
const FULL = "0x20-0x7E,0xA0-0xFF,0x2013,0x2019,0x2026";

const fonts = [
  ["c7", 88, "0123456789"],
  ["c7", 80, "0123456789:"],
  ["c7", 72, "0123456789"],
  ["c7", 64, "0123456789DAYP"],
  ["c7", 50, "0123456789:LIVE"],
  ["c7", 32, null],
  ["c7", 28, "0123456789"],
  ["c7", 24, "0123456789"],
  ["c6", 28, null],
  ["c6", 20, null],
  ...[10, 11, 12, 13].map(s => ["b7", s, null]),
  ...[9, 10, 11, 12, 13, 14].map(s => ["b6", s, null]),
  ...[10, 11, 12, 13].map(s => ["b5", s, null]),
];

mkdirSync("src/fonts", { recursive: true });
const decl = [];
for (const [fam, size, symbols] of fonts) {
  const name = `f_${fam}_${size}`;
  const args = ["--yes", "lv_font_conv@1.5.3", "--font", TTF[fam], "--size", String(size), "--bpp", "4",
                "--format", "lvgl", "--no-compress", "--lv-font-name", name, "-o", `src/fonts/${name}.c`];  // LVGL here has compressed fonts off
  // symbol fonts always get the space via a range (a literal space breaks Windows shell quoting)
  if (symbols) args.push("--symbols", symbols, "--range", "0x20"); else args.push("--range", FULL);
  execFileSync(process.platform === "win32" ? "npx.cmd" : "npx", args, { stdio: "inherit", shell: process.platform === "win32" });
  decl.push(`LV_FONT_DECLARE(${name})`);
  console.log("made", name);
}
writeFileSync("src/fonts/fonts.h",
  "// Generated by tools/make_fonts.mjs - Barlow / Barlow Condensed (SIL Open Font License)\n#pragma once\n#include <lvgl.h>\n\n" +
  decl.join("\n") + "\n");
